CSS='''*{box-sizing:border-box}body{margin:0;background:#f5f7f5;color:#243f4c;font:18px/1.8 system-ui,"Microsoft YaHei",sans-serif}header,main,nav{max-width:1080px;margin:auto}header{padding:42px 28px 25px}h1{font-size:32px;line-height:1.4;margin:10px 0}h2{font-size:27px}h3{font-size:21px}p{margin:12px 0 20px}.eyebrow{color:#6d8b8d;font-size:14px;letter-spacing:.15em}nav{display:flex;gap:10px;padding:12px 28px;position:sticky;top:0;background:#f5f7f5;z-index:3;flex-wrap:wrap}button{font:inherit;border:1px solid #bfd0cc;background:white;color:inherit;padding:10px 18px;border-radius:10px;cursor:pointer}button[aria-pressed=true],#run{background:#246e70;color:white}main{padding:10px 28px 65px}article,.panel,.workflow-step{background:white;border:1px solid #dce5e0;border-radius:14px;padding:24px;margin:20px 0}figure{margin:18px 0;max-width:720px}figure svg{display:block;width:100%;max-height:210px}figcaption{font-size:15px;color:#617b7d;margin-top:8px}.controls{display:flex;flex-wrap:wrap;gap:18px}label{display:grid;font-size:16px;min-width:210px;flex:1}input{font:inherit;padding:9px;border:1px solid #b7cbc8;border-radius:8px;width:100%}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:20px}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px}.metrics>div{background:#edf4f1;padding:15px;border-radius:10px}.metrics strong{display:block;font-size:26px}.metrics small{font-size:14px}.computed-chart{max-width:850px;margin:25px 0}.computed-chart svg{width:100%;height:auto}a{color:#24747a}.workflow-step dl{margin:0}.workflow-step dt{font-weight:700}.workflow-step dd{margin:0 0 12px}button:disabled{opacity:.5;cursor:default}[hidden]{display:none!important}@media(max-width:600px){body{font-size:17px}header,main{padding-left:17px;padding-right:17px}h1{font-size:27px}article,.panel,.workflow-step{padding:18px}nav{padding:8px 17px;gap:6px}nav button{padding:8px 10px;font-size:16px}.controls{display:grid}figure svg{max-height:180px}}'''
